 "content": "from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    marks = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 3]
    if not marks:
        return g

    rs = sorted({r for r, c in marks})
    cs = sorted({c for r, c in marks})
    # The marker is a full-width horizontal or full-height vertical band;
    # its thickness is the motif size.
    if len(cs) == w:
        n = len(rs)
    elif len(rs) == h:
        n = len(cs)
    else:
        n = min(len(rs), len(cs))
    step = n + 1
    row_starts = list(range(0, h - n + 1, step))
    col_starts = list(range(0, w - n + 1, step))

    motifs = []
    for ri, r0 in enumerate(row_starts):
        for ci, c0 in enumerate(col_starts):
            patch = tuple(tuple(g[r0+r][c0+c] for c in range(n)) for r in range(n))
            if any(v == 3 for row in patch for v in row):
                continue
            if any(v == 2 for row in patch for v in row):
                motifs.append((ri, ci, patch))
    if not motifs:
        return [[0 if v == 3 else v for v in row] for row in g]

    counts = Counter(p for _, _, p in motifs)
    dominant = counts.most_common(1)[0][0]

    # Mark each motif's cell indexed by its tile position; the repeated motif
    # also supplies the marked contents of eligible cells in the 3-band.
    for ri, ci, patch in motifs:
        if ri < n and ci < n and patch[ri][ci] == 2:
            g[row_starts[ri] + ri][col_starts[ci] + ci] = 8

    for ri, r0 in enumerate(row_starts):
        for ci, c0 in enumerate(col_starts):
            if not any(g[r0+r][c0+c] == 3 for r in range(n) for c in range(n)):
                continue
            for r in range(n):
                for c in range(n):
                    g[r0+r][c0+c] = dominant[r][c]
            if ri < n and ci < n and dominant[ri][ci] == 2:
                g[r0+ri][c0+ci] = 8
    return g
