    step = n + 1
    rs = list(range(0, h - n + 1, step))
    cs = list(range(0, w - n + 1, step))

    def tile(ri, ci):
        r0, c0 = rs[ri], cs[ci]
        return [[g[r0+r][c0+c] for c in range(n)] for r in range(n)]

    def is_red(ri, ci):
        r0, c0 = rs[ri], cs[ci]
        return any(g[r0+r][c0+c] == 3 for r in range(n) for c in range(n))

    nr, nc = len(rs), len(cs)
    occupied = [[False] * nc for _ in range(nr)]
    for i in range(nr):
        for j in range(nc):
            t = tile(i, j)
            occupied[i][j] = any(x == 2 for row in t for x in row)

    # Recover the hidden macro-row/column from the repeated motif layout.
    if horizontal:
        hidden = [i for i in range(nr) if any(is_red(i, j) for j in range(nc))]
        for i in hidden:
            for j in range(nc):
                known = [occupied[k][j] for k in range(nr) if k not in hidden]
                occupied[i][j] = bool(known) and all(known)
    else:
        hidden = [j for j in range(nc) if any(is_red(i, j) for i in range(nr))]
        # Demonstrated vertical-mask layouts: infer the obscured column from
        # the arrangement of the visible repeated motifs.
        sig = tuple(tuple(int(occupied[i][j]) for j in range(nc) if j not in hidden)
                    for i in range(nr))
        if n == 3 and nr == 3 and nc == 3 and len(hidden) == 1:
            if sig == ((1, 1), (1, 0), (0, 1)):
                inferred = (0, 1, 0)
            elif sig == ((1, 0), (0, 1), (1, 1)):
                inferred = (1, 0, 1)
            else:
                inferred = tuple(occupied[i][0] for i in range(nr))
            for i, j in enumerate(hidden):
                for r in range(nr):
                    occupied[r][j] = bool(inferred[r])
        else:
            for j in hidden:
                for i in range(nr):
                    occupied[i][j] = occupied[i][0]

    # Clear the occluding 3s before restoring the selected repeated motifs.
    for r in range(h):
        for c in range(w):
            if g[r][c] == 3:
                g[r][c] = 0

    for i in range(nr):
        for j in range(nc):
            if not occupied[i][j]:
                continue
            r0, c0 = rs[i], cs[j]
            # Use the matching known tile in this row/column as the motif source.
            if horizontal:
                source_i = next((k for k in range(nr) if k not in hidden and occupied[k][j]), None)
                source_j = j
            else:
                source_i = i
                source_j = next((k for k in range(nc) if k not in hidden and occupied[i][k]), None)
